def fill_illustration_id(apps, schema_editor):
    """Preenche o illustration_id das cartas já carregadas, sem consultar o Scryfall."""

    Card = apps.get_model("cards", "Card")

    for card in Card.objects.exclude(raw_scryfall=None).only("id", "raw_scryfall"):
        data = card.raw_scryfall or {}
        faces = data.get("card_faces") or [{}]
        illustration_id = data.get("illustration_id") or faces[0].get("illustration_id")

        if illustration_id:
            Card.objects.filter(pk=card.pk).update(illustration_id=illustration_id)


